UPDATE companies SET description='Colonial Wire & Cable of NJ traces its roots to 1944 in Edison, New Jersey, where it began as a family-owned enterprise. Now in its third generation, the company remains family-run, with ownership and daily operations kept within the founding family. The name and operating philosophy draw inspiration from the Colonial Minutemen, symbolizing rapid deployment and immediate response.

The company operates two manufacturing facilities: a residential cable and wiring plant in Hauppauge, New York, and a commercial wire and cable facility in Edison, New Jersey. Both produce copper electrical building wire for commercial, industrial, and residential applications. All products are made in the United States, and the company maintains an extensive inventory to support high fill rates and quick turnaround.

Colonial Wire & Cable sells exclusively through electrical distributors and wholesalers across North America. The company emphasizes direct manufacturer-to-distributor relationships, eliminating intermediate layers.

The Minutemen-inspired ethos drives a focus on prompt response and short lead times. Quality assurance is anchored by Underwriters Laboratory (UL) approval across more than 30 safety standards, with UL verification programs that include unannounced factory inspections and follow-up testing. The company also aligns with industry standards from ASTM, ICEA, IEEE, NEMA, NFPA, and the National Electrical Code.', certifications=ARRAY['UL Verification']::text[], profile='{"capabilities": ["Copper electrical building wire manufacturing", "Residential cable production", "Commercial wire production", "UL product verification and compliance testing"], "industries": ["Electrical distribution", "Electrical wholesale", "Commercial construction", "Industrial maintenance", "Residential construction"], "materials": ["Copper"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Prompt response and short lead times inspired by the Colonial Minutemen", "All products manufactured in the USA", "Direct manufacturer-to-distributor model with no middlemen", "Third-generation family-owned and operated"], "facts_used": ["Founded in 1944 -> /", "Headquartered in Edison, New Jersey -> db", "Third-generation family-owned and family-run -> /about-us", "Two manufacturing facilities: Hauppauge, NY (residential) and Edison, NJ (commercial) -> /about-us", "Manufactures copper electrical building wire for commercial, industrial, and residential use -> /", "Sells to electrical distributors and wholesalers throughout North America -> /", "All products made in the USA -> /", "Products approved by Underwriters Laboratory (UL) with UL Verification programs -> /about-us", "Industry standards: ASTM, ICEA, IEEE, NEMA, NFPA, NEC -> /", "Direct manufacturer, no middlemen -> /about-us", "Prompt response and short lead times -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "two state-of-the-art manufacturing facilities \u2013 one in Long Island, New York, for residential cable and wiring and a second in Edison, New Jersey, for commercial products", "founded_year": "1944", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='colonial-wire-cable-of-nj' AND approved AND profile IS NULL;
UPDATE companies SET description='Colorado Furniture operates a 10,000-square-foot showroom in Conifer, Colorado, along U.S. Highway 285. The business was founded in 2011 and is owned and operated by master designer Peggie Nikander, whose work includes the 2009 Colorado Parade of Homes Showcase Home in the Evergreen/Conifer area.

